92	    public boolean onPreferenceChange(Preference preference, Object newValue) {
93	        if (preference == serverNamePref) {
94	            sharedPreferences.edit()
95	                    .putString(Constants.PREFERENCES_KEY_SERVER_NAME + serverId, (String) newValue)
