104	                    throw new Exception();
105	                }
106	            } catch (Exception x) {
107	                new ErrorDialog(getActivity(), R.string.settings_invalid_url, false);
108	                return false;
109	            }
110	
111	            sharedPreferences.edit()
112	                    .putString(Constants.PREFERENCES_KEY_SERVER_URL + serverId, url)
113	                    .apply();
114	            updateUrl();
115	            return true;
116	        } else if (preference == serverUsernamePref) {
117	            String username = (String) newValue;
118	            if (username == null || !username.equals(username.trim())) {
119	                new ErrorDialog(getActivity(), R.string.settings_invalid_username, false);
120	                return false;
121	            }
122	
123	            sharedPreferences.edit()
124	                    .putString(Constants.PREFERENCES_KEY_USERNAME + serverId, username)
125	                    .apply();
