236	    private void testConnection() {
237	        ModalBackgroundTask<Boolean> task = new ModalBackgroundTask<Boolean>(getActivity(), false) {
238	            private int previousInstance;
239	
240	            @Override
241	            protected Boolean doInBackground() throws Throwable {
242	                updateProgress(R.string.settings_testing_connection);
243	
244	                final Context context = getActivity();
245	                previousInstance = Util.getActiveServer(context);
246	                Util.setActiveServer(context, serverId);
247	                try {
248	                    MusicService musicService = MusicServiceFactory.getMusicService(context);
249	                    musicService.ping(context, this);
250	                    return musicService.isLicenseValid(context, null);
251	                } finally {
252	                    Util.setActiveServer(context, previousInstance);
253	                }
254	            }
255	
256	            @Override
257	            protected void done(Boolean licenseValid) {
258	                if (licenseValid) {
259	                    Util.toast(getActivity(), R.string.settings_testing_ok);
260	                } else {
261	                    Util.toast(getActivity(), R.string.settings_testing_unlicensed);
262	                }
263	            }
264	
265	            @Override
266	            protected void cancel() {
267	                super.cancel();
268	                Util.setActiveServer(getActivity(), previousInstance);
269	            }
270	
271	            @Override
272	            protected void error(Throwable error) {
273	                Log.w(LOG_TAG, error.toString(), error);
274	                new ErrorDialog(getActivity(), String.format("%s %s", getResources().getString(R.string.settings_connection_failure), getErrorMessage(error)), false);
275	            }
276	        };
277	        task.execute();
278	    }
279	
280	    private void removeServer() {
281	        int activeServers = sharedPreferences
282	                .getInt(Constants.PREFERENCES_KEY_ACTIVE_SERVERS, 0);
283	
284	        // Clear permanent storage
285	        final String storageServerId = MusicServiceFactory.getServerId(sharedPreferences, serverId);
286	        final PermanentFileStorage fileStorage = new PermanentFileStorage(
287	                MusicServiceFactory.getDirectories(getActivity()),
288	                storageServerId,
289	                BuildConfig.DEBUG
290	        );
291	        fileStorage.clearAll();
292	
293	        // Reset values to null so when we ask for them again they are new
294	        sharedPreferences.edit()
295	                .remove(Constants.PREFERENCES_KEY_SERVER_NAME + serverId)
296	                .remove(Constants.PREFERENCES_KEY_SERVER_URL + serverId)
297	                .remove(Constants.PREFERENCES_KEY_USERNAME + serverId)
298	                .remove(Constants.PREFERENCES_KEY_PASSWORD + serverId)
299	                .remove(Constants.PREFERENCES_KEY_SERVER_ENABLED + serverId)
300	                .remove(Constants.PREFERENCES_KEY_JUKEBOX_BY_DEFAULT + serverId)
301	                .remove(Constants.PREFERENCES_KEY_ALLOW_SELF_SIGNED_CERTIFICATE + serverId)
302	                .apply();
303	
304	        if (serverId < activeServers) {
305	            int activeServer = Util.getActiveServer(getActivity());
306	            for (int i = serverId; i <= activeServers; i++) {
307	                Util.removeInstanceName(getActivity(), i, activeServer);
308	            }
309	        }
310	
311	        activeServers--;
312	
313	        sharedPreferences.edit()
314	                .putInt(Constants.PREFERENCES_KEY_ACTIVE_SERVERS, activeServers)
315	                .apply();
316	
317	        getActivity().finish();
318	    }
319	}
