    SubsonicTabActivity instance = SubsonicTabActivity.getInstance();

    if (instance != null) {
        ImageLoader imageLoader = instance.getImageLoader();

        if (imageLoader != null) {
            imageLoader.stopImageLoader();
            imageLoader.setConcurrency(concurrency);
        }
    }
}

